<script lang="ts" setup>
import { onMounted, ref } from 'vue';
import { message } from 'ant-design-vue';
import { createInfrastructureDevice, deleteInfrastructureDevice, getInfrastructureDeviceList, updateInfrastructureDevice, type InfrastructureDevice } from '#/api/scan/infrastructure-device';
import { getMachineRoomList } from '#/api/scan/machine-room';
import { useLocalTableSearch } from '../composables/useLocalTableSearch';
const props=defineProps<{deviceType:'network'|'storage';title:string}>();
const data=ref<InfrastructureDevice[]>([]),rooms=ref<any[]>([]),loading=ref(false),modalVisible=ref(false),editingId=ref<number>();
const {filteredRows,searchText}=useLocalTableSearch(data,['name','category','vendor','model','serial_number','management_ip','business_ip']);
const emptyForm=():InfrastructureDevice=>({device_type:props.deviceType,name:'',category:'',vendor:'',model:'',status:'active'});const form=ref(emptyForm());
const columns=[{title:'名称',dataIndex:'name'},{title:'类别',dataIndex:'category'},{title:'厂商/型号',key:'model'},{title:'序列号',dataIndex:'serial_number'},{title:'机房/机位',key:'location'},{title:'管理 IP',dataIndex:'management_ip'},{title:'业务 IP',dataIndex:'business_ip'},{title:'状态',key:'status'},{title:'操作',key:'actions',width:180}];
async function fetchData(){loading.value=true;try{const [rows,roomRows]=await Promise.all([getInfrastructureDeviceList(props.deviceType),getMachineRoomList()]);data.value=rows;rooms.value=roomRows as any;}catch{message.error('加载失败');}finally{loading.value=false;}}
function openCreate(){editingId.value=undefined;form.value=emptyForm();modalVisible.value=true;}function openEdit(row:InfrastructureDevice){editingId.value=row.id;form.value={...row};modalVisible.value=true;}
async function submit(){if(!form.value.name||!form.value.category){message.warning('请填写名称和类别');return;}try{if(editingId.value)await updateInfrastructureDevice(editingId.value,form.value);else await createInfrastructureDevice(form.value);message.success(editingId.value?'更新成功':'创建成功');modalVisible.value=false;await fetchData();}catch{message.error('保存失败');}}
onMounted(fetchData);
</script>
<template><div><a-page-header :title="title" :sub-title="deviceType==='network'?'维护交换机、路由器、负载均衡及其他网络硬件':'维护存储阵列、NAS、SAN 及备份设备'" style="padding:0;margin-bottom:16px"/><div class="device-toolbar"><a-button type="primary" @click="openCreate">新建{{ title }}</a-button><a-space :size="20"><a-input-search v-model:value="searchText" allow-clear placeholder="搜索名称、类别、厂商、型号或 IP" style="width:300px"/><a-button :loading="loading" @click="fetchData">刷新</a-button></a-space></div><a-table :columns="columns" :data-source="filteredRows" :loading="loading" row-key="id" :pagination="{pageSize:20}"><template #bodyCell="{column,record}"><template v-if="column.key==='model'">{{[record.vendor,record.model].filter(Boolean).join(' / ')||'-'}}</template><template v-else-if="column.key==='location'">{{rooms.find(room=>room.id===record.machine_room_id)?.room_name||'未绑定机房'}}<span v-if="record.rack_position"> / {{record.rack_position}}</span></template><template v-else-if="column.key==='status'"><a-tag :color="record.status==='active'?'green':'default'">{{record.status==='active'?'在用':'停用'}}</a-tag></template><template v-else-if="column.key==='actions'"><a-space :size="12"><a-button size="small" @click="openEdit(record)">编辑</a-button><a-popconfirm title="确认删除该设备？" @confirm="deleteInfrastructureDevice(record.id!).then(fetchData)"><a-button size="small" danger>删除</a-button></a-popconfirm></a-space></template></template></a-table>
<a-modal v-model:open="modalVisible" :title="editingId?`编辑${title}`:`新建${title}`" width="760px" @ok="submit"><a-form layout="vertical"><a-row :gutter="16"><a-col :span="12"><a-form-item label="设备名称" required><a-input v-model:value="form.name"/></a-form-item></a-col><a-col :span="12"><a-form-item label="设备类别" required><a-input v-model:value="form.category" :placeholder="deviceType==='network'?'交换机/路由器/负载均衡':'存储阵列/NAS/SAN/备份设备'"/></a-form-item></a-col><a-col :span="12"><a-form-item label="厂商"><a-input v-model:value="form.vendor"/></a-form-item></a-col><a-col :span="12"><a-form-item label="型号"><a-input v-model:value="form.model"/></a-form-item></a-col><a-col :span="12"><a-form-item label="序列号"><a-input v-model:value="form.serial_number"/></a-form-item></a-col><a-col :span="12"><a-form-item label="状态"><a-select v-model:value="form.status"><a-select-option value="active">在用</a-select-option><a-select-option value="inactive">停用</a-select-option></a-select></a-form-item></a-col><a-col :span="12"><a-form-item label="物理机房"><a-select v-model:value="form.machine_room_id" allow-clear :options="rooms.map(room=>({value:room.id,label:room.room_name}))"/></a-form-item></a-col><a-col :span="12"><a-form-item label="机柜/机位"><a-input v-model:value="form.rack_position"/></a-form-item></a-col><a-col :span="12"><a-form-item label="管理 IP"><a-input v-model:value="form.management_ip"/></a-form-item></a-col><a-col :span="12"><a-form-item label="业务 IP"><a-input v-model:value="form.business_ip"/></a-form-item></a-col><a-col :span="12"><a-form-item label="规格"><a-input v-model:value="form.specification"/></a-form-item></a-col><a-col :span="12"><a-form-item label="容量/性能"><a-input v-model:value="form.capacity"/></a-form-item></a-col><a-col :span="12"><a-form-item label="联系人"><a-input v-model:value="form.contact_person"/></a-form-item></a-col><a-col :span="12"><a-form-item label="联系电话"><a-input v-model:value="form.contact_phone"/></a-form-item></a-col><a-col :span="24"><a-form-item label="备注"><a-textarea v-model:value="form.remarks" :rows="3"/></a-form-item></a-col></a-row></a-form></a-modal></div></template>
<style scoped>.device-toolbar{display:flex;align-items:center;justify-content:space-between;gap:32px;margin-bottom:20px}@media(max-width:900px){.device-toolbar{align-items:flex-start;flex-direction:column}}</style>
